UIColouredSmokeEmitter=function(game,targetSprite,colour){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,45);this.targetSprite=targetSprite;this.particleClass=UIColouredSmokeParticle;this.makeParticles('game',['steam0','steam1','steam2']);this.minParticleSpeed.setTo(-40,-40);this.maxParticleSpeed.setTo(40,40);this.particleDrag.setTo(50,50);this.setAlpha(0.85,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.66;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE*1.0;this.gravity=0;this.smokeColour=colour;var i=0;this.forEach(function(particle){if(i++%3==0){particle.setColour(colour);}});this.kill();this.visible=false;};UIColouredSmokeEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIColouredSmokeEmitter.prototype.constructor=UIColouredSmokeEmitter;UIColouredSmokeEmitter.prototype.setSmokeColour=function(colour){this.smokeColour=colour;};UIColouredSmokeEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UIColouredSmokeEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);this.x=this.targetSprite.x;this.y=this.targetSprite.y;if(this.on&&!this.targetSprite.exists){this.on=false;}else if(this.on&&this.targetSprite.exists&&this.targetSprite.alpha<1.0){this.setAlpha(0.85*this.targetSprite.alpha,1.0*this.targetSprite.alpha);}if(this.countLiving()==0){this.kill();this.visible=false;}};UIColouredSmokeEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIColouredSmokeEmitter.prototype.spawn=function(x,y,frequency,colour){this.smokeColour=colour;this.revive();this.visible=true;this.x=x;this.y=y;this.setAlpha(0.85,1.0);this.explode(2000,1);this.start(false,2000,frequency,0,false);};UIColouredSmokeEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};